#!/usr/bin/env python3

#
# @file glfuncs
# @date 15-07-2024
# @author Maxim Kurylko <vk_vm@ukr.net>
#

import argparse
import re
from typing import Tuple, List

# Example: __DECL(PFNGLDELETEPROGRAMPROC, glDeleteProgram)
LINE_RE = re.compile(r'__DECL\((?P<type>[A-Z1-9]+), (?P<name>[a-zA-Z1-9]+)\)')

CPP_HEADER = """/*
 * This file is generated by glfuncs.py
 */
 
#include "yagecore/gl/glfuncs.hpp"
#include "yagecore/gl/util.hpp"
"""

HPP_HEADER = """/*
 * This file is generated by glfuncs.py
 */
 
#pragma once

#include <GL/gl.h>
#include <functional>

#if __has_include("cust_glfuncs.h")
#include "cust_glfuncs.h"
#endif
"""

def read_file(file: str) -> List[Tuple[str, str]]:
    with open(file, 'r') as f:
        lines = f.readlines()

    funcs = []
    for line in lines:
        match = LINE_RE.match(line)
        if match:
            funcs.append((match.group('type'), match.group('name')))
        else:
            print(f'Unmatched line: {line}')

    return funcs


def main():
    parser = argparse.ArgumentParser(description='Generate OpenGL functions')
    parser.add_argument('--input', type=str, help='Input file', required=True)
    parser.add_argument('--namespace', type=str, help='Namespace for generated functions', required=True)
    exclusive = parser.add_mutually_exclusive_group(required=True)
    exclusive.add_argument('--header', type=str, help='Generate header')
    exclusive.add_argument('--source', type=str, help='Generate source')
    args = parser.parse_args()

    funcs = read_file(args.input)
    if args.header:
        with open(args.header, 'w') as f:
            f.write(HPP_HEADER)
            f.write('\n')
            f.write(f'namespace {args.namespace} {{\n')
            f.write('\n')
            f.write('#if GL_AS_STD_FUNC\n')
            f.write('\n')
            f.write('template <typename T>\n')
            f.write('struct c_style_function;\n')
            f.write('template <typename R, typename... Args>\n')
            f.write('struct c_style_function<R(APIENTRY *)(Args...)>\n')
            f.write('{\n')
            f.write('    using cpp_style = std::function<R(Args...)>;\n')
            f.write('};\n')
            for func in funcs:
                f.write(f'extern c_style_function<{func[0]}>::cpp_style {func[1]};\n')
            f.write('\n')
            f.write('#else\n')
            f.write('\n')
            for func in funcs:
                f.write(f'extern {func[0]} {func[1]};\n')
            f.write('\n')
            f.write('#endif\n')
            f.write('void gl_update_cache();\n')
            f.write('}\n')
    elif args.source:
        with open(args.source, 'w') as f:
            f.write(CPP_HEADER)
            f.write('\n')
            f.write('\n')
            f.write('#if GL_AS_STD_FUNC\n')
            f.write('\n')
            for func in funcs:
                f.write(f'{args.namespace}::c_style_function<{func[0]}>::cpp_style {args.namespace}::{func[1]};\n')
            f.write('\n')
            f.write('#else\n')
            f.write('\n')
            for func in funcs:
                f.write(f'{func[0]} {args.namespace}::{func[1]};\n')
            f.write('\n')
            f.write('#endif\n')
            f.write(f'void {args.namespace}::gl_update_cache()\n')
            f.write('{\n')
            f.write('#if GL_AS_STD_FUNC\n')
            for func in funcs:
                f.write(f'    static auto {func[1]}_addr = reinterpret_cast<{func[0]}>(yc::gl::gl_lookup("{func[1]}", true));\n')
                f.write(f'    {args.namespace}::{func[1]} = [](auto&&... args) -> {args.namespace}::c_style_function<decltype({func[1]}_addr)>::cpp_style::result_type\n')
                f.write('    {\n')
                f.write(f'        return {func[1]}_addr(std::forward<decltype(args)>(args)...);\n')
                f.write('    };\n')
            f.write('#else\n')
            for func in funcs:
                f.write(f'    {args.namespace}::{func[1]} = reinterpret_cast<{func[0]}>(yc::gl::gl_lookup("{func[1]}", true));\n')
            f.write('#endif\n')
            f.write('}\n')

if __name__ == '__main__':
    main()
